import{_ as t,a,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 51 Predicting the future","description":"学习 将来完成时的截止视角，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 51 Predicting the future","description":"学习 将来完成时的截止视角，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 将来完成时的截止视角，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 50 New Year resolutions","link":"/life/english/new-concept/book-3/unit-03/lesson-050"},"next":{"text":"第三册：培养技能 · Lesson 52 Mud is mud","link":"/life/english/new-concept/book-3/unit-03/lesson-052"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 50 New Year resolutions","link":"/life/english/new-concept/book-3/unit-03/lesson-050"},"next":{"text":"第三册：培养技能 · Lesson 52 Mud is mud","link":"/life/english/new-concept/book-3/unit-03/lesson-052"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-051.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-051.md"}'),l={name:"life/english/new-concept/book-3/unit-03/lesson-051.md"};function o(r,e,s,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-51-predicting-the-future" tabindex="-1">第三册：培养技能 · Lesson 51 Predicting the future <a class="header-anchor" href="#第三册-培养技能-·-lesson-51-predicting-the-future" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 51 Predicting the future&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从技术预测与不确定性学习区分将完成的成果和将持续的过程。预测必须给出时间范围与依据，不能把语法上的将来形式当作保证。学习将来完成时描述截止点之前的状态，并用条件或情态表达提醒读者计划可能受到现实因素影响。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>forecast</td><td>/ˈfɔːkɑːst/</td><td>n.</td><td>预测</td><td>a cautious forecast</td></tr><tr><td>trend</td><td>/trend/</td><td>n.</td><td>趋势</td><td>a long-term trend</td></tr><tr><td>uncertainty</td><td>/ʌnˈsɜːtnti/</td><td>n.</td><td>不确定性</td><td>acknowledge uncertainty</td></tr><tr><td>estimate</td><td>/ˈestɪmeɪt/</td><td>v.</td><td>估计</td><td>estimate demand</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>by the time — 到……的时候，注意后续时态</li><li>on the basis of — 根据某证据或假设</li></ul><h2 id="语法讲解-将来完成时的截止视角" tabindex="-1">语法讲解：将来完成时的截止视角 <a class="header-anchor" href="#语法讲解-将来完成时的截止视角" aria-label="Permalink to &quot;语法讲解：将来完成时的截止视角&quot;">​</a></h2><p>will have 加过去分词表示到未来某个参照点之前已经完成的动作，常与 by 加时间或 by the time 从句配合。by the time 后的普通时间从句谈未来通常使用现在时，而不是 will。will be doing 则强调未来某时正在进行的动作，两者观察焦点不同。将来完成时可以用于预测或承诺，准确程度由证据与语境决定，语法形式不保证事实。若结果依赖条件，应明确加 if 或限定措辞，不要把目标直接写成确定的未来事实。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>If the schedule holds, the team will have tested all three models by Friday.</p></blockquote><p>如果进度如期进行，团队到周五将已测试完全部三个模型。</p><p>will have tested 以 Friday 为截止参照；if 从句使结果明确依赖进度条件。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>By the time she will arrive 不符合普通未来时间从句用法，应写 By the time she arrives。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 will have finished 与 will be testing，听辨 have 和 be；在 if 和 could 上突出条件性，避免语气过分确定。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The first two trials took one day each. If the remaining trials follow that pattern, we will have finished by Thursday. Unexpected equipment faults could still change the schedule.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句对虚构项目作谨慎预测，包含依据、截止点和不确定因素。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>以观察到的模式作条件预测，再指出模式可能失效的因素。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句保证任何情况下都能周五完成吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不保证。</p><p><strong>解析：</strong> if the schedule holds 是明确条件。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：By noon tomorrow, we will have ___ the report.（finished/finish）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> finished</p><p><strong>解析：</strong> 将来完成时需要过去分词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>will be testing 更强调过程还是完成？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 过程。</p><p><strong>解析：</strong> 将来进行时呈现某时正在进行。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：将来完成时的截止视角。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-050">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-052">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=t(l,[["render",o]]);export{p as __pageData,f as default};
